/**
 * @file    track.h
 * @brief   Five-channel infrared line sensor decode.
 *
 * The ITR9909 pair works by reflection: an infrared emitter fires at the
 * floor and a phototransistor measures what comes back.  White paper
 * reflects strongly (the comparator output goes low), black tape absorbs
 * (the output goes high).  Five of these sit in a row under the nose at
 * 12 mm spacing.
 *
 * The comparator threshold is trimmed by a potentiometer on each board; the
 * excitation signal generated by Track_Excite() is what keeps the emitters
 * from saturating the receivers, and is the reason this module also owns a
 * timer channel.
 */

#ifndef __TRACK_H__
#define __TRACK_H__

#include <stdint.h>

/* ---- decoded states -------------------------------------------------- */

typedef enum
{
    TRACK_LOST         = 0,     /* no channel sees the line             */
    TRACK_STRAIGHT     = 1,     /* centre channel(s) on the line        */
    TRACK_LEFT_SOFT    = 2,     /* line drifting left  — gentle correct */
    TRACK_LEFT_HARD    = 3,     /* line far left       — hard correct   */
    TRACK_RIGHT_SOFT   = 4,     /* line drifting right — gentle correct */
    TRACK_RIGHT_HARD   = 5,     /* line far right      — hard correct   */
    TRACK_ALL_BLACK    = 6      /* all five on black — cross or stop    */
} track_state_t;

/* ---- API ------------------------------------------------------------- */

void         Track_Init(void);

/** Drive the emitter excitation line; must be called every main-loop pass. */
void         Track_Excite(void);

/** Read all five channels at one instant into the caller's array. */
void         Track_Read(uint8_t *value);

/** Reduce the five channels to one of the track_state_t values. */
track_state_t Track_Decode(const uint8_t *value);

/** Human-readable name, for the OLED and the console. */
const char  *Track_StateName(track_state_t state);

#endif /* __TRACK_H__ */
